pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;

    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1_000_000);

        address player = address(0xBEEF);
        vm.deal(player, amount);

        bool callSucceeded;
        vm.prank(player);
        try c.play{value: amount}() {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }

        assertTrue(callSucceeded == (amount == 10));
    }
}
